import Foundation

extension FinanceGuides {
    static let pensionGuide = DirectoryGuide(
        cardSummary: .init(ukrainian: "Австрійський стаж, українська пенсія та подання заяв", german: "Österreichische Zeiten, ukrainische Pension und Anträge"),
        introduction: .init(ukrainian: "Розділіть два питання: право на австрійську пенсію та отримання пенсії з України. Перевіряйте умови в кожній країні окремо.", german: "Zwei Fragen getrennt prüfen: Anspruch auf eine österreichische Pension und Bezug einer Pension aus der Ukraine. Voraussetzungen in jedem Land gesondert klären."),
        sections: [
            .init("coverage", "briefcase", "Чи робота дає пенсійне страхування", "Ist Ihre Arbeit pensionsversichert?", "Звірте зарплатні відомості й дані Sozialversicherung. Одна лише geringfügige Beschäftigung зазвичай дає страхування від нещасних випадків, але не обов’язкове пенсійне страхування. Якщо маєте кілька робіт або хочете добровільно застрахуватися, з’ясуйте свій випадок у страховій установі.", "Lohnzettel und Sozialversicherungsdaten abgleichen. Eine einzelne geringfügige Beschäftigung umfasst grundsätzlich Unfallversicherung, aber keine Pflicht-Pensionsversicherung. Bei mehreren Jobs oder Interesse an Selbstversicherung den Einzelfall mit dem Versicherungsträger klären.", source: pensionLowIncome),
            .init("account", "clock.arrow.circlepath", "Звірте австрійські страхові місяці", "Österreichische Versicherungsmonate abgleichen", "Перегляньте Pensionskonto або попросіть Versicherungsdatenauszug у PV. Звірте роботодавців, місяці роботи й зараховані періоди догляду за дитиною. Якщо чогось немає, надішліть PV докази та попросіть перевірити запис до подання заяви.", "Pensionskonto einsehen oder bei der PV einen Versicherungsdatenauszug anfordern. Arbeitgeber, Arbeitsmonate und anrechenbare Kindererziehungszeiten abgleichen. Fehlt etwas, Nachweise an die PV senden und den Eintrag vor Antragstellung prüfen lassen.", source: pensionRecord),
            .init("foreign", "globe.europe.africa", "Не рахуйте український стаж автоматично", "Ukrainische Zeiten nicht automatisch anrechnen", "PV координує періоди в ЄС/ЄЕЗ і державах із відповідною угодою. У чинному переліку PV Україна не вказана: робота в Україні сама по собі не додає австрійських страхових місяців для набуття права. Повідомте PV про весь іноземний стаж, але попросіть письмово пояснити, які періоди можна врахувати у вашій справі.", "Die PV koordiniert Zeiten aus EU/EWR-Staaten und Staaten mit entsprechendem Abkommen. Die Ukraine steht nicht in der aktuellen PV-Liste: Beschäftigung dort schafft für sich genommen keine österreichischen Versicherungsmonate für den Anspruch. Alle Auslandszeiten dennoch der PV mitteilen und im Einzelfall schriftlich klären lassen, welche Zeiten berücksichtigt werden.", source: pension),
            .init("ukrainian-pension", "doc.text", "Українську пенсію оформлюйте через ПФУ", "Ukrainische Pension über den PFU beantragen", "Право на українську пенсію та її розмір перевіряє ПФУ за українськими правилами. Зберіть паспортні дані, відомості про стаж і наявні рішення. Заяву можна подати через офіційний портал ПФУ з електронним підписом або Дія.Підписом, якщо цей спосіб вам доступний. Австрійська заява не замінює українську.", "Anspruch und Höhe einer ukrainischen Pension prüft der PFU nach ukrainischem Recht. Identitätsdaten, Beschäftigungsnachweise und vorhandene Bescheide bereithalten. Der Antrag kann über das offizielle PFU-Portal mit elektronischer Signatur oder Diia-Signatur eingereicht werden, wenn dieser Zugang verfügbar ist. Ein österreichischer Antrag ersetzt den ukrainischen nicht.", source: ukrainianPension),
            .init("identification", "person.crop.circle.badge.checkmark", "Якщо вже отримуєте пенсію з України", "Wenn Sie bereits ukrainische Pension beziehen", "Перевіряйте повідомлення ПФУ й актуальність контактних даних. Для пенсіонерів за кордоном ПФУ описує фізичну ідентифікацію; спосіб і строки залежать від ситуації та чинних правил. Якщо виплата зупинилася, з’ясуйте причину в ПФУ та збережіть підтвердження звернення.", "Mitteilungen des PFU und aktuelle Kontaktdaten prüfen. Für Pensionistinnen und Pensionisten im Ausland beschreibt der PFU eine Identifizierung; Weg und Fristen hängen von der Situation und aktuellen Regeln ab. Wurde die Zahlung gestoppt, Ursache beim PFU klären und Nachweise der Kontaktaufnahme aufbewahren.", source: ukrainianIdentification),
            .init("apply", "calendar", "Австрійську заяву плануйте заздалегідь", "Österreichischen Antrag rechtzeitig planen", "Домовтеся з PV про перевірку виду пенсії, страхових місяців і дати початку. PV радить подавати заяву на звичайну пенсію за віком приблизно за три місяці до бажаного початку. Підготуйте посвідчення особи, номер соціального страхування й докази відсутніх періодів. Окремо з’ясуйте вплив обох пенсій на медичне страхування та соціальні виплати.", "Mit der PV Pensionsart, Versicherungsmonate und Stichtag prüfen. Die PV empfiehlt den Antrag auf Alterspension etwa drei Monate vor dem gewünschten Beginn. Ausweis, Sozialversicherungsnummer und Nachweise fehlender Zeiten vorbereiten. Auswirkungen beider Pensionen auf Krankenversicherung und Sozialleistungen gesondert klären.", source: pensionApplication)
        ], sources: [pensionLowIncome, pensionRecord, pension, ukrainianPension, ukrainianIdentification, pensionApplication]
    )
}
